1	// ===== Estado global =====
2	const DIFFICULTY = {
3	    easy: { label: 'Fácil', maxGuesses: 9 },
4	    medium: { label: 'Média', maxGuesses: 7 },
5	    hard: { label: 'Difícil', maxGuesses: 5 }
6	};
7	const ROUND_SECONDS = 45;
8	
9	const state = {
10	    mode: localStorage.getItem('hangman.mode') || 'solo',
11	    difficulty: localStorage.getItem('hangman.difficulty') || 'medium',
12	    category: 'all',
13	    soundOn: localStorage.getItem('hangman.sound') !== 'off',
14	    theme: localStorage.getItem('hangman.theme') || 'light',
15	    selectedWord: '',
16	    hint: '',
17	    guessed: [],
18	    wrong: 0,
19	    maxGuesses: DIFFICULTY.medium.maxGuesses,
20	    active: false,
21	    result: null,
22	    currentTurn: 0,
23	    roundDraws: 0,
24	    timerId: null,
25	    timeLeft: 0,
26	    hintUsed: false
27	};
28	
29	// ===== DOM =====
30	const wordDisplayElement = document.getElementById('wordDisplay');
31	const guessesElement = document.getElementById('guesses');
32	const messageElement = document.getElementById('message');
33	const newGameBtn = document.getElementById('newGameBtn');
34	const keyElements = Array.from(document.querySelectorAll('.key'));
35	const fireworksCanvas = document.getElementById('fireworksCanvas');
36	const categorySelect = document.getElementById('categorySelect');
37	const scoreboard = document.getElementById('scoreboard');
38	const roundText = document.getElementById('roundText');
39	const timerText = document.getElementById('timerText');
40	const hintBtn = document.getElementById('hintBtn');
41	const revealBtn = document.getElementById('revealBtn');
42	const hintText = document.getElementById('hintText');
43	const themeToggle = document.getElementById('themeToggle');
44	const soundToggle = document.getElementById('soundToggle');
45	
46	// ===== Áudio (Web Audio API) =====
47	let audioCtx = null;
48	
49	function ensureAudio() {
50	    if (!audioCtx) {
51	        try {
52	            audioCtx = new (window.AudioContext || window.webkitAudioContext)();
53	        } catch (e) {
54	            audioCtx = null;
55	        }
56	    }
57	    if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
58	}
59	
60	function tone(freq, duration, delay, type = 'sine', gainValue = 0.12) {
61	    if (!state.soundOn || !audioCtx) return;
62	    const start = audioCtx.currentTime + delay;
63	    const osc = audioCtx.createOscillator();
64	    const gain = audioCtx.createGain();
65	    osc.type = type;
66	    osc.frequency.value = freq;
67	    gain.gain.setValueAtTime(gainValue, start);
68	    gain.gain.exponentialRampToValueAtTime(0.001, start + duration);
69	    osc.connect(gain).connect(audioCtx.destination);
70	    osc.start(start);
71	    osc.stop(start + duration);
72	}
73	
74	function playCorrect() { ensureAudio(); tone(520, 0.12, 0); tone(660, 0.15, 0.08); }
75	function playWrong() { ensureAudio(); tone(160, 0.25, 0, 'square', 0.08); }
76	function playWin() {
77	    ensureAudio();
78	    [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.22, i * 0.13, 'triangle', 0.14));
79	}
80	function playLose() {
81	    ensureAudio();
82	    [392, 330, 262, 196].forEach((f, i) => tone(f, 0.25, i * 0.15, 'sawtooth', 0.07));
83	}
84	
85	// ===== Placar (localStorage) =====
86	function loadScore(key, fallback) {
87	    try {
88	        const raw = localStorage.getItem(key);
89	        return raw ? JSON.parse(raw) : fallback;
90	    } catch (e) {
91	        return fallback;
92	    }
93	}
94	
95	function saveScore(key, value) {
96	    try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) { /* modo privado */ }
97	}
98	
99	const soloFallback = { wins: 0, losses: 0, streak: 0, bestStreak: 0, draws: 0 };
100	let soloScore = loadScore('hangman.solo', soloFallback);
101	let duelScore = loadScore('hangman.duel', { p1: 0, p2: 0, draws: 0 });
102	
103	function renderScoreboard() {
104	    scoreboard.innerHTML = '';
105	    if (state.mode === 'solo') {
106	        const cards = [
107	            { name: 'Vitórias', value: soloScore.wins },
108	            { name: 'Derrotas', value: soloScore.losses },
109	            { name: 'Sequência', value: soloScore.streak },
110	            { name: 'Recorde', value: soloScore.bestStreak }
111	        ];
112	        cards.forEach(c => {
113	            const div = document.createElement('div');
114	            div.className = 'score-card';
115	            div.innerHTML = `<div class="name">${c.name}</div><div class="score-value">${c.value}</div>`;
116	            scoreboard.appendChild(div);
117	        });
118	    } else {
119	        const cards = [
120	            { name: 'Jogador 1', value: duelScore.p1, turn: state.currentTurn === 0 },
121	            { name: 'Jogador 2', value: duelScore.p2, turn: state.currentTurn === 1 },
122	            { name: 'Empates', value: duelScore.draws }
123	        ];
124	        cards.forEach(c => {
125	            const div = document.createElement('div');
126	            div.className = 'score-card' + (c.turn ? ' turn' : '');
127	            div.innerHTML = `<div class="name">${c.name}</div><div class="score-value">${c.value}</div>`;
128	            scoreboard.appendChild(div);
129	        });
130	    }
131	}
132	
133	// ===== Palavras =====
134	function buildCategoryOptions() {
135	    const options = ['all'].concat(HangmanWordList.categoryList);
136	    categorySelect.innerHTML = '';
137	    options.forEach(opt => {
138	        const el = document.createElement('option');
139	        el.value = opt;
140	        el.textContent = opt === 'all' ? 'Todas' : HangmanWordList.categoryList.find(c => c.toLowerCase() === opt);
141	        categorySelect.appendChild(el);
142	    });
143	}
144	
145	function pickWord() {
146	    let pool = HangmanWordList.words;
147	    if (state.category !== 'all') {
148	        pool = pool.filter(w => w.category.toLowerCase() === state.category);
149	    }
150	    const unique = [];
151	    const seen = new Set();
152	    for (const w of pool) {
153	        if (!seen.has(w.word)) { seen.add(w.word); unique.push(w); }
154	    }
155	    return unique[Math.floor(Math.random() * unique.length)];
156	}
157	
158	// ===== Desenho da forca =====
159	// Corda, cabeça, tronco, 2 braços e 2 pernas = 7 partes
160	const hangmanParts = ['rope', 'head', 'body', 'leftArm', 'rightArm', 'leftLeg', 'rightLeg'];
161	
162	function drawHangmanPart() {
163	    // Re-rendere conforme o nº de erros, animando cada parte com CSS
164	    hangmanParts.forEach((id, i) => {
165	        const el = document.getElementById(id);
166	        if (i < state.wrong) {
167	            if (!el.classList.contains('drawn')) {
168	                requestAnimationFrame(() => el.classList.add('drawn'));
169	            }
170	        } else {
171	            el.classList.remove('drawn');
172	        }
173	    });
174	    updateFace();
175	}
176	
177	function resetHangman() {
178	    hangmanParts.forEach(id => document.getElementById(id).classList.remove('drawn'));
179	    face.classList.remove('visible', 'dead', 'fear', 'win', 'tired', 'talking');
180	    setBrows('relaxed');
181	    document.getElementById('mouth').setAttribute('d', MOUTHS.happy);
182	    [eyeL, eyeR].forEach(eye => {
183	        const pupil = eye.querySelector('.pupil');
184	        if (pupil) pupil.style.transform = '';
185	        eye.classList.remove('blink');
186	    });
187	}
