189	// ===== Expressões do stickman =====
190	const face = document.getElementById('face');
191	const eyeL = document.getElementById('eyeL');
192	const eyeR = document.getElementById('eyeR');
193	const browL = document.getElementById('browL');
194	const browR = document.getElementById('browR');
195	let blinkInterval = null;
196	let lookTimer = null;
197	let talkTimeout = null;
198	
199	const MOUTHS = {
200	    happy: 'M133 90 Q140 97 147 90',
201	    neutral: 'M134 92 Q140 93 146 92',
202	    worried: 'M134 93 Q140 91 146 93',
203	    scared: 'M138 89 Q140 99 142 89',
204	    dead: 'M134 93 Q140 90 146 93'
205	};
206	
207	const BROWS = {
208	    relaxed:      { l: 'M128 73 Q133 69 138 73', r: 'M142 73 Q147 69 152 73' },
209	    tired:        { l: 'M128 74 Q133 72.5 138 73.5', r: 'M142 73.5 Q147 72.5 152 74' },
210	    worried:      { l: 'M128 74.5 Q133 72 138 74', r: 'M142 74 Q147 72 152 74.5' },
211	    scared:       { l: 'M128 71.5 Q133 73 138 71.5', r: 'M142 71.5 Q147 73 152 71.5' }
212	};
213	
214	function setBrows(expr) {
215	    if (!BROWS[expr]) return;
216	    browL.setAttribute('d', BROWS[expr].l);
217	    browR.setAttribute('d', BROWS[expr].r);
218	}
219	
220	function updateFace() {
221	    if (!face) return;
222	    const headDrawn = document.getElementById('head').classList.contains('drawn');
223	    const ratio = state.maxGuesses > 0 ? state.wrong / state.maxGuesses : 0;
224	
225	    face.classList.remove('win', 'fear', 'dead', 'tired');
226	
227	    if (!headDrawn) {
228	        face.classList.remove('visible');
229	        return;
230	    }
231	    face.classList.add('visible');
232	
233	    if (state.result === 'win') {
234	        // Vitória: relaxa
235	        setBrows('relaxed');
236	        document.getElementById('mouth').setAttribute('d', MOUTHS.happy);
237	        face.classList.add('win');
238	        return;
239	    }
240	
241	    if (state.result === 'lose' || state.wrong >= state.maxGuesses) {
242	        setBrows('relaxed');
243	        state.result = 'lose';
244	        document.getElementById('mouth').setAttribute('d', MOUTHS.dead);
245	        face.classList.add('dead');
246	        [eyeL, eyeR].forEach(eye => {
247	            const pupil = eye.querySelector('.pupil');
248	            if (pupil) pupil.style.transform = '';
249	        });
250	        return;
251	    }
252	
253	    // Jogando: a expressão piora conforme perde tentativas
254	    if (ratio >= 0.7) {
255	        setBrows('scared');
256	        document.getElementById('mouth').setAttribute('d', MOUTHS.scared);
257	        face.classList.add('fear');
258	    } else if (ratio >= 0.45) {
259	        setBrows('worried');
260	        document.getElementById('mouth').setAttribute('d', MOUTHS.worried);
261	        face.classList.add('fear');
262	    } else if (ratio >= 0.28) {
263	        setBrows('tired');
264	        document.getElementById('mouth').setAttribute('d', MOUTHS.neutral);
265	        face.classList.add('tired');
266	    } else {
267	        setBrows('relaxed');
268	        document.getElementById('mouth').setAttribute('d', MOUTHS.happy);
269	    }
270	}
271	
272	function talkFace() {
273	    if (!face) return;
274	    face.classList.add('talking');
275	    clearTimeout(talkTimeout);
276	    talkTimeout = setTimeout(() => face.classList.remove('talking'), 1600);
277	}
278	
279	// Piscadas periódicas
280	function startBlinking() {
281	    if (blinkInterval) return;
282	    blinkInterval = true;
283	    let next = 2200;
284	    const schedule = () => {
285	        setTimeout(() => {
286	            if (!face.classList.contains('dead')) {
287	                eyeL.classList.add('blink');
288	                eyeR.classList.add('blink');
289	                setTimeout(() => {
290	                    eyeL.classList.remove('blink');
291	                    eyeR.classList.remove('blink');
292	                }, 130);
293	            }
294	            next = 1800 + Math.random() * 3400;
295	            schedule();
296	        }, next);
297	    };
298	    schedule();
299	}
300	
301	// Pupila segue o mouse enquanto está vivo
302	function startEyeFollowing() {
303	    if (lookTimer) return;
304	    lookTimer = document.addEventListener('mousemove', (e) => {
305	        if (face.classList.contains('dead') || !face.classList.contains('visible')) return;
306	        const eyes = [eyeL, eyeR];
307	        for (const eye of eyes) {
308	            const pupil = eye.querySelector('.pupil');
309	            if (!pupil) continue;
310	            const rect = eye.getBoundingClientRect();
311	            if (rect.width === 0) continue;
312	            const dx = e.clientX - (rect.left + rect.width / 2);
313	            const dy = e.clientY - (rect.top + rect.height / 2);
314	            const dist = Math.hypot(dx, dy);
315	            if (dist < 220) {
316	                const max = 2.6;
317	                const t = dist / 220;
318	                pupil.style.transform = `translate(${(dx / dist) * max * t}px, ${(dy / dist) * max * t}px)`;
319	            } else {
320	                pupil.style.transform = '';
321	            }
322	        }
323	    });
324	}
325	
326	// ===== Jogo =====
327	function displayWord() {
328	    let display = '';
329	    for (const ch of state.selectedWord) {
330	        display += state.guessed.includes(ch) ? ch + ' ' : '_ ';
331	    }
332	    wordDisplayElement.textContent = display.trim();
333	}
334	
335	function isWin() {
336	    return state.selectedWord.split('').every(ch => state.guessed.includes(ch));
337	}
338	
339	function remainingLettersInWord() {
340	    const inWord = new Set(state.selectedWord.split(''));
341	    return [...inWord].filter(ch => !state.guessed.includes(ch));
342	}
343	
344	function updateRevealBtn() {
345	    revealBtn.disabled = !state.active || remainingLettersInWord().length === 0 || state.wrong >= state.maxGuesses;
346	}
347	
348	function hint() {
349	    if (!state.active || state.hintUsed) return;
350	    state.hintUsed = true;
351	    hintText.textContent = `Dica: ${state.hint}`;
352	    hintBtn.disabled = true;
353	    talkFace();
354	}
355	
356	function revealLetter() {
357	    if (!state.active || state.wrong >= state.maxGuesses) return;
358	    const options = remainingLettersInWord();
359	    if (options.length === 0) return;
360	    const letter = options[Math.floor(Math.random() * options.length)];
361	    state.guessed.push(letter);
362	    state.wrong++;
363	    guessesElement.textContent = state.maxGuesses - state.wrong;
364	    drawHangmanPart();
365	    displayWord();
366	    markKey(letter, 'correct', true);
367	    playWrong();
368	    messageElSoft('Letra revelada por -1 tentativa.');
369	    if (isWin()) { endRound(true, state.currentTurn); return; }
370	    if (state.wrong >= state.maxGuesses) { endRound(false, null); return; }
371	    if (state.mode === 'duel') {
372	        switchTurn();
373	        startTimer();
374	    }
375	    updateRevealBtn();
376	}
377	
378	function markKey(letter, cls, disabled) {
379	    keyElements.forEach(key => {
380	        if (key.dataset.letter === letter) {
381	            key.classList.add(cls);
382	            key.disabled = disabled;
383	        }
384	    });
385	}
386	
387	function messageElSoft(text) {
388	    messageElement.textContent = text;
389	    messageElement.style.color = '';
390	}
391	
392	function switchTurn() {
393	    state.currentTurn = state.currentTurn === 0 ? 1 : 0;
394	    renderScoreboard();
395	    updateRoundInfo();
396	}
397	
398	function updateRoundInfo() {
399	    if (state.mode === 'duel') {
400	        const name = state.currentTurn === 0 ? 'Jogador 1' : 'Jogador 2';
401	        roundText.textContent = state.active ? `Vez de ${name}` : 'Rodada finalizada';
402	    } else {
403	        roundText.textContent = `Dificuldade: ${DIFFICULTY[state.difficulty].label} • ${state.category === 'all' ? 'Todas as categorias' : HangmanWordList.categoryList.find(c => c.toLowerCase() === state.category)}`;
404	    }
405	}
406	
407	function startTimer() {
408	    if (state.timerId) clearInterval(state.timerId);
409	    state.timerId = null;
410	
411	    // O timer só tem efeito no modo duelo (troca o turno ao zerar)
412	    if (state.mode !== 'duel') {
413	        state.timeLeft = 0;
414	        renderTimer();
415	        return;
416	    }
417	
418	    state.timeLeft = ROUND_SECONDS;
419	    renderTimer();
420	    state.timerId = setInterval(() => {
421	        state.timeLeft--;
422	        renderTimer();
423	        if (state.timeLeft <= 0) {
424	            if (state.wrong >= state.maxGuesses) { endRound(false, null); return; }
425	            switchTurn();
426	            startTimer();
427	        }
428	    }, 1000);
429	}
430	
431	function stopTimer() {
432	    if (state.timerId) { clearInterval(state.timerId); state.timerId = null; }
433	}
434	
435	function renderTimer() {
436	    timerText.textContent = state.mode === 'duel' ? `⏱ ${Math.max(0, state.timeLeft)}s` : '';
437	}
438	
439	function handleGuess(letter) {
440	    if (!state.active || state.guessed.includes(letter)) return;
441	
442	    state.guessed.push(letter);
443	    const correct = state.selectedWord.includes(letter);
444	    markKey(letter, correct ? 'correct' : 'incorrect', true);
445	    displayWord();
446	
447	    if (correct) {
448	        playCorrect();
449	        if (isWin()) {
450	            endRound(true, state.currentTurn);
451	            return;
452	        }
453	        // Acerto não consome a vez no modo duelo (quem acertou continua)
454	        updateRevealBtn();
455	        return;
456	    }
457	
458	    state.wrong++;
459	    guessesElement.textContent = state.maxGuesses - state.wrong;
460	    drawHangmanPart();
461	    playWrong();
462	    if (state.wrong >= state.maxGuesses) {
463	        endRound(false, null);
464	        return;
465	    }
466	    if (state.mode === 'duel') {
467	        switchTurn();
468	        startTimer();
469	    }
470	    updateRevealBtn();
471	}
472	
473	function endRound(won, winnerTurn) {
474	    state.active = false;
475	    state.result = won ? 'win' : 'lose';
476	    stopTimer();
477	    keyElements.forEach(key => key.disabled = true);
478	    hintBtn.disabled = true;
479	    revealBtn.disabled = true;
480	
481	    if (won) {
482	        playWin();
483	        if (state.mode === 'solo') {
484	            soloScore.wins++;
485	            soloScore.streak++;
486	            if (soloScore.streak > soloScore.bestStreak) soloScore.bestStreak = soloScore.streak;
487	            saveScore('hangman.solo', soloScore);
488	            messageElement.textContent = 'Parabéns! Você venceu!';
489	        } else {
490	            if (winnerTurn === 0) duelScore.p1++; else duelScore.p2++;
491	            saveScore('hangman.duel', duelScore);
492	            const name = winnerTurn === 0 ? 'Jogador 1' : 'Jogador 2';
493	            messageElement.textContent = `Parabéns! ${name} venceu!`;
494	        }
495	        messageElement.style.color = 'var(--correct)';
496	        triggerFireworks();
497	        updateFace();
498	    } else {
499	        playLose();
500	        if (state.mode === 'solo') {
501	            soloScore.losses++;
502	            soloScore.streak = 0;
503	            saveScore('hangman.solo', soloScore);
504	        } else {
505	            duelScore.draws++;
506	            saveScore('hangman.duel', duelScore);
507	        }
508	        messageElement.textContent = `Fim das tentativas! A palavra era: ${state.selectedWord}. Dica: ${state.hint}`;
509	        messageElement.style.color = 'var(--incorrect)';
510	        updateFace();
511	    }
512	
513	    // Revela a palavra no display
514	    state.guessed = [...new Set(state.selectedWord.split(''))];
515	    displayWord();
516	    keyElements.forEach(key => {
517	        const l = key.dataset.letter;
518	        if (state.selectedWord.includes(l)) {
519	            key.classList.remove('incorrect');
520	            key.classList.add('correct');
521	        }
522	    });
523	
524	    newGameBtn.textContent = state.mode === 'duel' ? 'Nova Rodada' : 'Novo Jogo';
525	    renderScoreboard();
526	    updateRoundInfo();
527	}
528	
529	function initRound(startTurn) {
530	    stopTimer();
531	    const chosen = pickWord();
532	    state.selectedWord = chosen.word.toUpperCase();
533	    state.hint = chosen.hint;
534	    state.guessed = [];
535	    state.wrong = 0;
536	    state.maxGuesses = DIFFICULTY[state.difficulty].maxGuesses;
537	    state.active = true;
538	    state.result = null;
539	    state.hintUsed = false;
540	    if (startTurn !== undefined) state.currentTurn = startTurn % 2;
541	
542	    guessesElement.textContent = state.maxGuesses;
543	    messageElement.textContent = '';
544	    hintText.textContent = '';
545	    hintBtn.disabled = false;
546	    categorySelect.disabled = false;
547	    displayWord();
548	    resetHangman();
549	    keyElements.forEach(key => {
550	        key.disabled = false;
551	        key.classList.remove('correct', 'incorrect');
552	    });
553	    fireworksCanvas.style.display = 'none';
554	    if (fireworkEngine) fireworkEngine.stop();
555	    updateRevealBtn();
556	    updateRoundInfo();
557	    renderScoreboard();
558	    startTimer();
559	}
560	
561	// ===== Fogos =====
562	let fireworkEngine = null;
563	let fireworksTimeout;
564	
565	function triggerFireworks() {
566	    if (!fireworkEngine) return;
567	    fireworksCanvas.style.display = 'block';
568	    fireworkEngine.start();
569	
570	    const w = window.innerWidth;
571	    const h = window.innerHeight;
572	    const explosionCount = 10;
573	    for (let i = 0; i < explosionCount; i++) {
574	        setTimeout(() => {
575	            if (fireworkEngine.explosions.length < FireworkConfig.maxExplosions) {
576	                const x = Math.random() * w;
577	                const y = Math.random() * h * 0.7;
578	                const color = FireworkConfig.colors[Math.floor(Math.random() * FireworkConfig.colors.length)];
579	                fireworkEngine.createExplosion(x, y, color);
580	                fireworkEngine.createFallingLines(x, y, color);
581	            }
582	        }, Math.random() * 2000);
583	    }
584	
585	    clearTimeout(fireworksTimeout);
586	    fireworksTimeout = setTimeout(() => {
587	        fireworkEngine.stop();
588	        fireworksCanvas.style.display = 'none';
589	    }, 5000);
590	}
591	
592	// ===== Configurações de UI =====
593	function applyTheme() {
594	    document.documentElement.setAttribute('data-theme', state.theme);
595	    themeToggle.textContent = state.theme === 'dark' ? 'Tema Claro' : 'Tema Escuro';
596	    themeToggle.setAttribute('aria-pressed', state.theme === 'dark' ? 'true' : 'false');
597	}
598	
599	function applySoundToggle() {
600	    soundToggle.textContent = state.soundOn ? 'Som: Ligado' : 'Som: Desligado';
601	    soundToggle.setAttribute('aria-pressed', state.soundOn ? 'true' : 'false');
602	}
603	
604	function setActiveBtns(group, value, attr) {
605	    group.querySelectorAll('button').forEach(btn => {
606	        btn.classList.toggle('active', btn.getAttribute(attr) === value);
607	    });
608	}
609	
610	// ===== Inicialização =====
