// ===== Estado global =====
const DIFFICULTY = {
    easy: { label: 'Fácil', maxGuesses: 9 },
    medium: { label: 'Média', maxGuesses: 7 },
    hard: { label: 'Difícil', maxGuesses: 5 }
};
const ROUND_SECONDS = 45;

const state = {
    mode: localStorage.getItem('hangman.mode') || 'solo',
    difficulty: localStorage.getItem('hangman.difficulty') || 'medium',
    category: 'all',
    soundOn: localStorage.getItem('hangman.sound') !== 'off',
    theme: localStorage.getItem('hangman.theme') || 'light',
    selectedWord: '',
    hint: '',
    guessed: [],
    wrong: 0,
    maxGuesses: DIFFICULTY.medium.maxGuesses,
    active: false,
    result: null,
    currentTurn: 0,
    roundDraws: 0,
    timerId: null,
    timeLeft: 0,
    hintUsed: false
};

// ===== DOM =====
const wordDisplayElement = document.getElementById('wordDisplay');
const guessesElement = document.getElementById('guesses');
const messageElement = document.getElementById('message');
const newGameBtn = document.getElementById('newGameBtn');
const keyElements = Array.from(document.querySelectorAll('.key'));
const fireworksCanvas = document.getElementById('fireworksCanvas');
const categorySelect = document.getElementById('categorySelect');
const scoreboard = document.getElementById('scoreboard');
const roundText = document.getElementById('roundText');
const timerText = document.getElementById('timerText');
const hintBtn = document.getElementById('hintBtn');
const revealBtn = document.getElementById('revealBtn');
const hintText = document.getElementById('hintText');
const themeToggle = document.getElementById('themeToggle');
const soundToggle = document.getElementById('soundToggle');

// ===== Áudio (Web Audio API) =====
let audioCtx = null;

function ensureAudio() {
    if (!audioCtx) {
        try {
            audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        } catch (e) {
            audioCtx = null;
        }
    }
    if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}

function tone(freq, duration, delay, type = 'sine', gainValue = 0.12) {
    if (!state.soundOn || !audioCtx) return;
    const start = audioCtx.currentTime + delay;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = type;
    osc.frequency.value = freq;
    gain.gain.setValueAtTime(gainValue, start);
    gain.gain.exponentialRampToValueAtTime(0.001, start + duration);
    osc.connect(gain).connect(audioCtx.destination);
    osc.start(start);
    osc.stop(start + duration);
}

function playCorrect() { ensureAudio(); tone(520, 0.12, 0); tone(660, 0.15, 0.08); }
function playWrong() { ensureAudio(); tone(160, 0.25, 0, 'square', 0.08); }
function playWin() {
    ensureAudio();
    [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.22, i * 0.13, 'triangle', 0.14));
}
function playLose() {
    ensureAudio();
    [392, 330, 262, 196].forEach((f, i) => tone(f, 0.25, i * 0.15, 'sawtooth', 0.07));
}

// ===== Placar (localStorage) =====
function loadScore(key, fallback) {
    try {
        const raw = localStorage.getItem(key);
        return raw ? JSON.parse(raw) : fallback;
    } catch (e) {
        return fallback;
    }
}

function saveScore(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) { /* modo privado */ }
}

const soloFallback = { wins: 0, losses: 0, streak: 0, bestStreak: 0, draws: 0 };
let soloScore = loadScore('hangman.solo', soloFallback);
let duelScore = loadScore('hangman.duel', { p1: 0, p2: 0, draws: 0 });

function renderScoreboard() {
    scoreboard.innerHTML = '';
    if (state.mode === 'solo') {
        const cards = [
            { name: 'Vitórias', value: soloScore.wins },
            { name: 'Derrotas', value: soloScore.losses },
            { name: 'Sequência', value: soloScore.streak },
            { name: 'Recorde', value: soloScore.bestStreak }
        ];
        cards.forEach(c => {
            const div = document.createElement('div');
            div.className = 'score-card';
            div.innerHTML = `<div class="name">${c.name}</div><div class="score-value">${c.value}</div>`;
            scoreboard.appendChild(div);
        });
    } else {
        const cards = [
            { name: 'Jogador 1', value: duelScore.p1, turn: state.currentTurn === 0 },
            { name: 'Jogador 2', value: duelScore.p2, turn: state.currentTurn === 1 },
            { name: 'Empates', value: duelScore.draws }
        ];
        cards.forEach(c => {
            const div = document.createElement('div');
            div.className = 'score-card' + (c.turn ? ' turn' : '');
            div.innerHTML = `<div class="name">${c.name}</div><div class="score-value">${c.value}</div>`;
            scoreboard.appendChild(div);
        });
    }
}

// ===== Palavras =====
function buildCategoryOptions() {
    const options = ['all'].concat(HangmanWordList.categoryList);
    categorySelect.innerHTML = '';
    options.forEach(opt => {
        const el = document.createElement('option');
        el.value = opt;
        el.textContent = opt === 'all' ? 'Todas' : HangmanWordList.categoryList.find(c => c.toLowerCase() === opt);
        categorySelect.appendChild(el);
    });
}

function pickWord() {
    let pool = HangmanWordList.words;
    if (state.category !== 'all') {
        pool = pool.filter(w => w.category.toLowerCase() === state.category);
    }
    const unique = [];
    const seen = new Set();
    for (const w of pool) {
        if (!seen.has(w.word)) { seen.add(w.word); unique.push(w); }
    }
    return unique[Math.floor(Math.random() * unique.length)];
}

// ===== Desenho da forca =====
// Corda, cabeça, tronco, 2 braços e 2 pernas = 7 partes
const hangmanParts = ['rope', 'head', 'body', 'leftArm', 'rightArm', 'leftLeg', 'rightLeg'];

function drawHangmanPart() {
    // Re-rendere conforme o nº de erros, animando cada parte com CSS
    hangmanParts.forEach((id, i) => {
        const el = document.getElementById(id);
        if (i < state.wrong) {
            if (!el.classList.contains('drawn')) {
                requestAnimationFrame(() => el.classList.add('drawn'));
            }
        } else {
            el.classList.remove('drawn');
        }
    });
    updateFace();
}

function resetHangman() {
    hangmanParts.forEach(id => document.getElementById(id).classList.remove('drawn'));
    face.classList.remove('visible', 'dead', 'fear', 'win', 'tired', 'talking');
    setBrows('relaxed');
    document.getElementById('mouth').setAttribute('d', MOUTHS.happy);
    [eyeL, eyeR].forEach(eye => {
        const pupil = eye.querySelector('.pupil');
        if (pupil) pupil.style.transform = '';
        eye.classList.remove('blink');
    });
}

// ===== Expressões do stickman =====
const face = document.getElementById('face');
const eyeL = document.getElementById('eyeL');
const eyeR = document.getElementById('eyeR');
const browL = document.getElementById('browL');
const browR = document.getElementById('browR');
let blinkInterval = null;
let lookTimer = null;
let talkTimeout = null;

const MOUTHS = {
    happy: 'M133 90 Q140 97 147 90',
    neutral: 'M134 92 Q140 93 146 92',
    worried: 'M134 93 Q140 91 146 93',
    scared: 'M138 89 Q140 99 142 89',
    dead: 'M134 93 Q140 90 146 93'
};

const BROWS = {
    relaxed:      { l: 'M128 73 Q133 69 138 73', r: 'M142 73 Q147 69 152 73' },
    tired:        { l: 'M128 74 Q133 72.5 138 73.5', r: 'M142 73.5 Q147 72.5 152 74' },
    worried:      { l: 'M128 74.5 Q133 72 138 74', r: 'M142 74 Q147 72 152 74.5' },
    scared:       { l: 'M128 71.5 Q133 73 138 71.5', r: 'M142 71.5 Q147 73 152 71.5' }
};

function setBrows(expr) {
    if (!BROWS[expr]) return;
    browL.setAttribute('d', BROWS[expr].l);
    browR.setAttribute('d', BROWS[expr].r);
}

function updateFace() {
    if (!face) return;
    const headDrawn = document.getElementById('head').classList.contains('drawn');
    const ratio = state.maxGuesses > 0 ? state.wrong / state.maxGuesses : 0;

    face.classList.remove('win', 'fear', 'dead', 'tired');

    if (!headDrawn) {
        face.classList.remove('visible');
        return;
    }
    face.classList.add('visible');

    if (state.result === 'win') {
        // Vitória: relaxa
        setBrows('relaxed');
        document.getElementById('mouth').setAttribute('d', MOUTHS.happy);
        face.classList.add('win');
        return;
    }

    if (state.result === 'lose' || state.wrong >= state.maxGuesses) {
        setBrows('relaxed');
        state.result = 'lose';
        document.getElementById('mouth').setAttribute('d', MOUTHS.dead);
        face.classList.add('dead');
        [eyeL, eyeR].forEach(eye => {
            const pupil = eye.querySelector('.pupil');
            if (pupil) pupil.style.transform = '';
        });
        return;
    }

    // Jogando: a expressão piora conforme perde tentativas
    if (ratio >= 0.7) {
        setBrows('scared');
        document.getElementById('mouth').setAttribute('d', MOUTHS.scared);
        face.classList.add('fear');
    } else if (ratio >= 0.45) {
        setBrows('worried');
        document.getElementById('mouth').setAttribute('d', MOUTHS.worried);
        face.classList.add('fear');
    } else if (ratio >= 0.28) {
        setBrows('tired');
        document.getElementById('mouth').setAttribute('d', MOUTHS.neutral);
        face.classList.add('tired');
    } else {
        setBrows('relaxed');
        document.getElementById('mouth').setAttribute('d', MOUTHS.happy);
    }
}

function talkFace() {
    if (!face) return;
    face.classList.add('talking');
    clearTimeout(talkTimeout);
    talkTimeout = setTimeout(() => face.classList.remove('talking'), 1600);
}

// Piscadas periódicas
function startBlinking() {
    if (blinkInterval) return;
    blinkInterval = true;
    let next = 2200;
    const schedule = () => {
        setTimeout(() => {
            if (!face.classList.contains('dead')) {
                eyeL.classList.add('blink');
                eyeR.classList.add('blink');
                setTimeout(() => {
                    eyeL.classList.remove('blink');
                    eyeR.classList.remove('blink');
                }, 130);
            }
            next = 1800 + Math.random() * 3400;
            schedule();
        }, next);
    };
    schedule();
}

// Pupila segue o mouse enquanto está vivo
function startEyeFollowing() {
    if (lookTimer) return;
    lookTimer = document.addEventListener('mousemove', (e) => {
        if (face.classList.contains('dead') || !face.classList.contains('visible')) return;
        const eyes = [eyeL, eyeR];
        for (const eye of eyes) {
            const pupil = eye.querySelector('.pupil');
            if (!pupil) continue;
            const rect = eye.getBoundingClientRect();
            if (rect.width === 0) continue;
            const dx = e.clientX - (rect.left + rect.width / 2);
            const dy = e.clientY - (rect.top + rect.height / 2);
            const dist = Math.hypot(dx, dy);
            if (dist < 220) {
                const max = 2.6;
                const t = dist / 220;
                pupil.style.transform = `translate(${(dx / dist) * max * t}px, ${(dy / dist) * max * t}px)`;
            } else {
                pupil.style.transform = '';
            }
        }
    });
}

// ===== Jogo =====
function displayWord() {
    let display = '';
    for (const ch of state.selectedWord) {
        display += state.guessed.includes(ch) ? ch + ' ' : '_ ';
    }
    wordDisplayElement.textContent = display.trim();
}

function isWin() {
    return state.selectedWord.split('').every(ch => state.guessed.includes(ch));
}

function remainingLettersInWord() {
    const inWord = new Set(state.selectedWord.split(''));
    return [...inWord].filter(ch => !state.guessed.includes(ch));
}

function updateRevealBtn() {
    revealBtn.disabled = !state.active || remainingLettersInWord().length === 0 || state.wrong >= state.maxGuesses;
}

function hint() {
    if (!state.active || state.hintUsed) return;
    state.hintUsed = true;
    hintText.textContent = `Dica: ${state.hint}`;
    hintBtn.disabled = true;
    talkFace();
}

function revealLetter() {
    if (!state.active || state.wrong >= state.maxGuesses) return;
    const options = remainingLettersInWord();
    if (options.length === 0) return;
    const letter = options[Math.floor(Math.random() * options.length)];
    state.guessed.push(letter);
    state.wrong++;
    guessesElement.textContent = state.maxGuesses - state.wrong;
    drawHangmanPart();
    displayWord();
    markKey(letter, 'correct', true);
    playWrong();
    messageElSoft('Letra revelada por -1 tentativa.');
    if (isWin()) { endRound(true, state.currentTurn); return; }
    if (state.wrong >= state.maxGuesses) { endRound(false, null); return; }
    if (state.mode === 'duel') {
        switchTurn();
        startTimer();
    }
    updateRevealBtn();
}

function markKey(letter, cls, disabled) {
    keyElements.forEach(key => {
        if (key.dataset.letter === letter) {
            key.classList.add(cls);
            key.disabled = disabled;
        }
    });
}

function messageElSoft(text) {
    messageElement.textContent = text;
    messageElement.style.color = '';
}

function switchTurn() {
    state.currentTurn = state.currentTurn === 0 ? 1 : 0;
    renderScoreboard();
    updateRoundInfo();
}

function updateRoundInfo() {
    if (state.mode === 'duel') {
        const name = state.currentTurn === 0 ? 'Jogador 1' : 'Jogador 2';
        roundText.textContent = state.active ? `Vez de ${name}` : 'Rodada finalizada';
    } else {
        roundText.textContent = `Dificuldade: ${DIFFICULTY[state.difficulty].label} • ${state.category === 'all' ? 'Todas as categorias' : HangmanWordList.categoryList.find(c => c.toLowerCase() === state.category)}`;
    }
}

function startTimer() {
    if (state.timerId) clearInterval(state.timerId);
    state.timerId = null;

    // O timer só tem efeito no modo duelo (troca o turno ao zerar)
    if (state.mode !== 'duel') {
        state.timeLeft = 0;
        renderTimer();
        return;
    }

    state.timeLeft = ROUND_SECONDS;
    renderTimer();
    state.timerId = setInterval(() => {
        state.timeLeft--;
        renderTimer();
        if (state.timeLeft <= 0) {
            if (state.wrong >= state.maxGuesses) { endRound(false, null); return; }
            switchTurn();
            startTimer();
        }
    }, 1000);
}

function stopTimer() {
    if (state.timerId) { clearInterval(state.timerId); state.timerId = null; }
}

function renderTimer() {
    timerText.textContent = state.mode === 'duel' ? `⏱ ${Math.max(0, state.timeLeft)}s` : '';
}

function handleGuess(letter) {
    if (!state.active || state.guessed.includes(letter)) return;

    state.guessed.push(letter);
    const correct = state.selectedWord.includes(letter);
    markKey(letter, correct ? 'correct' : 'incorrect', true);
    displayWord();

    if (correct) {
        playCorrect();
        if (isWin()) {
            endRound(true, state.currentTurn);
            return;
        }
        // Acerto não consome a vez no modo duelo (quem acertou continua)
        updateRevealBtn();
        return;
    }

    state.wrong++;
    guessesElement.textContent = state.maxGuesses - state.wrong;
    drawHangmanPart();
    playWrong();
    if (state.wrong >= state.maxGuesses) {
        endRound(false, null);
        return;
    }
    if (state.mode === 'duel') {
        switchTurn();
        startTimer();
    }
    updateRevealBtn();
}

function endRound(won, winnerTurn) {
    state.active = false;
    state.result = won ? 'win' : 'lose';
    stopTimer();
    keyElements.forEach(key => key.disabled = true);
    hintBtn.disabled = true;
    revealBtn.disabled = true;

    if (won) {
        playWin();
        if (state.mode === 'solo') {
            soloScore.wins++;
            soloScore.streak++;
            if (soloScore.streak > soloScore.bestStreak) soloScore.bestStreak = soloScore.streak;
            saveScore('hangman.solo', soloScore);
            messageElement.textContent = 'Parabéns! Você venceu!';
        } else {
            if (winnerTurn === 0) duelScore.p1++; else duelScore.p2++;
            saveScore('hangman.duel', duelScore);
            const name = winnerTurn === 0 ? 'Jogador 1' : 'Jogador 2';
            messageElement.textContent = `Parabéns! ${name} venceu!`;
        }
        messageElement.style.color = 'var(--correct)';
        triggerFireworks();
        updateFace();
    } else {
        playLose();
        if (state.mode === 'solo') {
            soloScore.losses++;
            soloScore.streak = 0;
            saveScore('hangman.solo', soloScore);
        } else {
            duelScore.draws++;
            saveScore('hangman.duel', duelScore);
        }
        messageElement.textContent = `Fim das tentativas! A palavra era: ${state.selectedWord}. Dica: ${state.hint}`;
        messageElement.style.color = 'var(--incorrect)';
        updateFace();
    }

    // Revela a palavra no display
    state.guessed = [...new Set(state.selectedWord.split(''))];
    displayWord();
    keyElements.forEach(key => {
        const l = key.dataset.letter;
        if (state.selectedWord.includes(l)) {
            key.classList.remove('incorrect');
            key.classList.add('correct');
        }
    });

    newGameBtn.textContent = state.mode === 'duel' ? 'Nova Rodada' : 'Novo Jogo';
    renderScoreboard();
    updateRoundInfo();
}

function initRound(startTurn) {
    stopTimer();
    const chosen = pickWord();
    state.selectedWord = chosen.word.toUpperCase();
    state.hint = chosen.hint;
    state.guessed = [];
    state.wrong = 0;
    state.maxGuesses = DIFFICULTY[state.difficulty].maxGuesses;
    state.active = true;
    state.result = null;
    state.hintUsed = false;
    if (startTurn !== undefined) state.currentTurn = startTurn % 2;

    guessesElement.textContent = state.maxGuesses;
    messageElement.textContent = '';
    hintText.textContent = '';
    hintBtn.disabled = false;
    categorySelect.disabled = false;
    displayWord();
    resetHangman();
    keyElements.forEach(key => {
        key.disabled = false;
        key.classList.remove('correct', 'incorrect');
    });
    fireworksCanvas.style.display = 'none';
    if (fireworkEngine) fireworkEngine.stop();
    updateRevealBtn();
    updateRoundInfo();
    renderScoreboard();
    startTimer();
}

// ===== Fogos =====
let fireworkEngine = null;
let fireworksTimeout;

function triggerFireworks() {
    if (!fireworkEngine) return;
    fireworksCanvas.style.display = 'block';
    fireworkEngine.start();

    const w = window.innerWidth;
    const h = window.innerHeight;
    const explosionCount = 10;
    for (let i = 0; i < explosionCount; i++) {
        setTimeout(() => {
            if (fireworkEngine.explosions.length < FireworkConfig.maxExplosions) {
                const x = Math.random() * w;
                const y = Math.random() * h * 0.7;
                const color = FireworkConfig.colors[Math.floor(Math.random() * FireworkConfig.colors.length)];
                fireworkEngine.createExplosion(x, y, color);
                fireworkEngine.createFallingLines(x, y, color);
            }
        }, Math.random() * 2000);
    }

    clearTimeout(fireworksTimeout);
    fireworksTimeout = setTimeout(() => {
        fireworkEngine.stop();
        fireworksCanvas.style.display = 'none';
    }, 5000);
}

// ===== Configurações de UI =====
function applyTheme() {
    document.documentElement.setAttribute('data-theme', state.theme);
    themeToggle.textContent = state.theme === 'dark' ? 'Tema Claro' : 'Tema Escuro';
    themeToggle.setAttribute('aria-pressed', state.theme === 'dark' ? 'true' : 'false');
}

function applySoundToggle() {
    soundToggle.textContent = state.soundOn ? 'Som: Ligado' : 'Som: Desligado';
    soundToggle.setAttribute('aria-pressed', state.soundOn ? 'true' : 'false');
}

function setActiveBtns(group, value, attr) {
    group.querySelectorAll('button').forEach(btn => {
        btn.classList.toggle('active', btn.getAttribute(attr) === value);
    });
}

// ===== Inicialização =====
document.addEventListener('DOMContentLoaded', () => {
    if (typeof FireworkEngine === 'function') {
        fireworkEngine = new FireworkEngine();
        fireworkEngine.init('fireworksCanvas');
    } else {
        console.warn('FireworkEngine indisponível: fogos de artifício desativados.');
    }

    buildCategoryOptions();
    categorySelect.value = state.category;

    setActiveBtns(document.getElementById('modeGroup'), state.mode, 'data-mode');
    setActiveBtns(document.getElementById('difficultyGroup'), state.difficulty, 'data-diff');
    applyTheme();
    applySoundToggle();

    // Modo
    document.querySelectorAll('#modeGroup button').forEach(btn => {
        btn.addEventListener('click', () => {
            state.mode = btn.dataset.mode;
            localStorage.setItem('hangman.mode', state.mode);
            setActiveBtns(document.getElementById('modeGroup'), state.mode, 'data-mode');
            renderScoreboard();
            renderTimer();
        });
    });

    // Dificuldade
    document.querySelectorAll('#difficultyGroup button').forEach(btn => {
        btn.addEventListener('click', () => {
            state.difficulty = btn.dataset.diff;
            localStorage.setItem('hangman.difficulty', state.difficulty);
            setActiveBtns(document.getElementById('difficultyGroup'), state.difficulty, 'data-diff');
            updateRoundInfo();
        });
    });

    // Categoria
    categorySelect.addEventListener('change', () => {
        state.category = categorySelect.value;
        updateRoundInfo();
    });

    // Som
    soundToggle.addEventListener('click', () => {
        state.soundOn = !state.soundOn;
        localStorage.setItem('hangman.sound', state.soundOn ? 'on' : 'off');
        applySoundToggle();
    });

    // Tema
    themeToggle.addEventListener('click', () => {
        state.theme = state.theme === 'dark' ? 'light' : 'dark';
        localStorage.setItem('hangman.theme', state.theme);
        applyTheme();
    });

    // Botões do jogo
    keyElements.forEach(key => {
        key.addEventListener('click', () => handleGuess(key.dataset.letter));
    });

    newGameBtn.addEventListener('click', () => {
        const startTurn = state.mode === 'duel' ? (state.roundDraws >= 0 ? (state.roundDraws + 1) % 2 : 0) : 0;
        state.roundDraws++;
        initRound(startTurn);
    });

    hintBtn.addEventListener('click', hint);
    revealBtn.addEventListener('click', revealLetter);

    // Teclado físico
    document.addEventListener('keydown', (event) => {
        if (event.ctrlKey || event.metaKey || event.altKey) return;
        const key = event.key.toUpperCase();
        if (key.length === 1 && key >= 'A' && key <= 'Z') {
            handleGuess(key);
        } else if (key === 'ENTER' && !state.active) {
            newGameBtn.click();
        }
    });

    renderScoreboard();
    startBlinking();
    startEyeFollowing();
    initRound(0);
});
